std::vector<uint8_t> syntheticAssets(){std::vector<uint8_t>b(0xa800,0);for(unsigned i=0;i<102;++i)b[0x7aac+i]=2;b[0x777c+('A'-32)*8]=0x80;b[0x777c+('B'-32)*8]=0x40;for(unsigned i=0;i<6;++i)b[0x777c+(0x80+i-32)*8]=uint8_t(0x80u>>(i%3));
 const unsigned r=0xecb6-0xd400;const uint8_t record[]={0x41,0,0,1,0x77,0xa4,0xbc,0xe0,0,0,3,0x20};for(unsigned i=0;i<12;++i)b[r+i]=record[i];auto zeroBlock=[&b](size_t at,unsigned count){b[at++]=uint8_t(count>>8);b[at++]=uint8_t(count);std::vector<std::vector<uint8_t> > tokens;tokens.push_back(std::vector<uint8_t>(1,0));unsigned remaining=count-1;while(remaining){unsigned n=remaining>33?33:remaining;if(n<3)throw std::runtime_error("test compressed count");std::vector<uint8_t> token;token.push_back(uint8_t(n-3));token.push_back(1);tokens.push_back(token);remaining-=n;}tokens.push_back(std::vector<uint8_t>(1,0x1f));for(size_t i=0;i<tokens.size();i+=8){uint8_t flags=0;for(size_t n=i;n<tokens.size()&&n<i+8;++n)if(n)flags|=uint8_t(1u<<(n-i));b[at++]=flags;for(size_t n=i;n<tokens.size()&&n<i+8;++n)for(uint8_t value:tokens[n])b[at++]=value;}};zeroBlock(0xa3a4,800);zeroBlock(0xa4f8,512);const unsigned cr=0xecc4-0xd400;const uint8_t cursor[]={0x11,0,0,1,0x78,0xf8,0xde,0,0,0,2,0};for(unsigned i=0;i<12;++i)b[cr+i]=cursor[i];const unsigned geometry=0xecd2-0xd400;b[geometry+1]=2; // one all-zero8x8piece at relative frame2
 const unsigned table=0x13552-0xd400;for(unsigned i=0;i<48;++i){b[table+i*2]=0;b[table+i*2+1]=96;}b[table+96]=0x32;b[table+97]='A';b[table+98]=0xff;
 const unsigned prompt=0x1387c-0xd400;for(unsigned variant=0;variant<3;++variant){unsigned start=prompt+variant*24;b[start+6]=0xee;b[start+7]=0x3a;b[start+16]=0xee;b[start+17]=0x7a;}b[0x1391c-0xd400+1]=12;b[0x1391c-0xd400+3]=4;return b;}
uint8_t pixel(const std::vector<uint8_t>&b,unsigned x,unsigned y){size_t at=((y/8)*32+x/8)*32+(y&7)*4+(x&7)/2;return (x&1)?b[at]&15:b[at]>>4;}
void focused(){using namespace Snatcher;std::string e;DialogueWindow w;std::vector<uint8_t> assets=syntheticAssets();check(w.loadAssets(assets.data(),assets.size(),e),"owned synthetic format assets");DialogueLayout unknown,layout=freshModuleDialogueLayout();const uint8_t lines[]={'A','B',0xf2,'A',0xff};check(!w.begin(lines,sizeof(lines),0,0,unknown,e),"unknown inherited layout explicitly rejects");check(w.begin(lines,sizeof(lines),0,0,layout,e),"source no-speaker line entry");for(unsigned i=0;i<100&&!w.waiting();++i)check(w.tick(false,e),"finite line update");check(w.waiting()&&w.textEnded(),"linebreak advances then actual terminator");check(pixel(w.patterns(),24,0)==1&&pixel(w.patterns(),27,0)==1&&pixel(w.patterns(),24,9)==1,"proportional glyph pixels and9pixel line pitch");std::vector<uint8_t> prior=w.patterns();check(!w.begin(lines,sizeof(lines)-1,0,0,layout,e)&&w.patterns()==prior,"failed unterminated entry preserves old page");check(!w.begin(lines,sizeof(lines),0,49,layout,e)&&w.patterns()==prior,"out-of-directory speaker rejects transactionally");check(w.acknowledge(e)&&w.tick(false,e)&&w.finished()&&!w.active(),"terminal input ends owned dialogue");check(!w.acknowledge(e),"duplicate acknowledgement rejected");check(w.begin(lines,sizeof(lines),0,2,layout,e),"speaker name through directory");for(unsigned i=0;i<100&&!w.waiting();++i)check(w.tick(false,e),"named line update");check(pixel(w.patterns(),16,0)==2&&pixel(w.patterns(),24,9)==1,"speaker header color remains separate from body");const uint8_t paused[]={'A',0xf6,'B',0xff};check(w.begin(paused,sizeof(paused),0,0,layout,e),"source explicit text pause");for(unsigned i=0;i<100&&!w.waiting();++i)check(w.tick(false,e),"pause page update");check(!w.textEnded()&&w.waiting()&&w.revealedGlyphs()==1,"pause retains unconsumed source");check(w.acknowledge(e)&&!w.waiting(),"page input resumes remaining text");for(unsigned i=0;i<100&&!w.waiting();++i)check(w.tick(false,e),"second page update");check(w.waiting()&&w.textEnded()&&w.revealedGlyphs()==2,"continuation consumes one remaining glyph");layout.fixedWidth=true;const uint8_t ab[]={'A','B',0xff};check(w.begin(ab,sizeof(ab),0,0,layout,e),"fixed width owner");for(unsigned i=0;i<100&&!w.waiting();++i)check(w.tick(false,e),"fixed width update");check(pixel(w.patterns(),24,0)==1&&pixel(w.patterns(),34,0)==1,"fixed9 advance independent of proportional width");const uint8_t contextual[]={0xec,0xff};check(!w.begin(contextual,sizeof(contextual),0,0,layout,e),"unowned contextual substitution rejects");layout.substitutionKnown=true;layout.substitution=0;check(w.begin(contextual,sizeof(contextual),0,0,layout,e),"owned controller substitution");for(unsigned i=0;i<100&&!w.waiting();++i)check(w.tick(false,e),"contextual glyph update");check(w.revealedGlyphs()==1,"contextual action produces one original glyph");std::vector<uint8_t> menuSource(0x3900,0xff);menuSource[0x3800]='A';menuSource[0x380a]='B';std::vector<uint16_t> refs={0,10};layout.fixedWidth=false;check(w.beginMenu(menuSource.data(),menuSource.size(),refs,1,layout,e),"identity-keyed original menu");check(pixel(w.patterns(),16,0)==4&&pixel(w.patterns(),17,9)==1,"selected row white and inactive row cyan");std::vector<PlacedPiece> cursor;check(w.menuPieces(cursor,e)&&cursor.size()==1&&cursor[0].x==16&&cursor[0].y==152,"original cursor row pitch");check(!w.acknowledge(e),"dialogue acknowledgement cannot select menu");std::vector<uint16_t> tooMany(9,0);prior=w.patterns();check(!w.beginMenu(menuSource.data(),menuSource.size(),tooMany,0,layout,e)&&w.patterns()==prior,"beyond two source pages retains owner");check(!w.beginMenu(menuSource.data(),menuSource.size(),refs,2,layout,e),"menu selection outside identity list rejected");std::vector<uint16_t> paged(8,0);for(unsigned selected=0;selected<8;++selected){check(w.beginMenu(menuSource.data(),menuSource.size(),paged,selected,layout,e)&&w.menuPieces(cursor,e),"original two-page standard menu");unsigned row=selected<6?selected:selected-5;check(cursor[0].y==143+int(row)*9,"page cursor skips source arrow rows");}check(pixel(w.patterns(),124,0)==1&&pixel(w.patterns(),125,0)==4&&pixel(w.patterns(),126,0)==5,"page arrow color planes overlay at original sharedx124");layout.variant=1;paged.resize(8);for(unsigned selected=0;selected<8;++selected){check(w.beginMenu(menuSource.data(),menuSource.size(),paged,selected,layout,e)&&w.menuPieces(cursor,e),"original two-page alternate menu");unsigned row=selected<5?selected:selected-4;check(cursor[0].y==159+int(row)*9,"alternate source page cursor mapping");}check(w.beginMenu(menuSource.data(),menuSource.size(),paged,0,layout,e)&&pixel(w.patterns(),124,45)==1&&pixel(w.patterns(),125,45)==4&&pixel(w.patterns(),126,45)==5,"alternate down arrow uses source row45 and overlay");layout.variant=0;std::fill(menuSource.begin()+0x3800,menuSource.begin()+0x3820,uint8_t('A'));menuSource[0x3820]=0xff;check(w.beginMenu(menuSource.data(),menuSource.size(),std::vector<uint16_t>(1,0),0,layout,e),"bounded32glyph label owns terminator");prior=w.patterns();menuSource[0x3820]='A';check(!w.beginMenu(menuSource.data(),menuSource.size(),std::vector<uint16_t>(1,0),0,layout,e)&&w.patterns()==prior,"unterminated33byte label does not invent inherited tail");w.cancel();check(!w.active()&&!w.waiting()&&!w.finished(),"cancel removes pending input ownership");std::vector<GraphicsTransfer> out;check(!w.transfers(out,e)&&out.empty(),"cancelled owner does not fabricate allocations");}
