void fastRevealContracts(){using namespace Snatcher;std::string e;auto assets=syntheticAssets();auto layout=freshModuleDialogueLayout();DialogueWindow normal,fast;const uint8_t line[]={'A','B','A',0xff};
 check(normal.loadAssets(assets.data(),assets.size(),e)&&fast.loadAssets(assets.data(),assets.size(),e),"fast reveal format assets");
 check(normal.begin(line,sizeof(line),0,0,layout,e)&&fast.begin(line,sizeof(line),0,0,layout,e),"fast reveal actual body delay producer");
 for(unsigned i=0;i<2;++i)check(normal.tick(false,e)&&fast.tick(false,e),"same source prefix before confirm");
 check(normal.revealedGlyphs()==1&&fast.revealedGlyphs()==1,"source delay1 reveals one glyph after delay command");
 auto before=fast.patterns();check(fast.tick(true,e,true)&&fast.patterns()==before&&fast.revealedGlyphs()==1,"paused confirm does not mutate reveal owner");
 check(fast.tick(false,e,true)&&fast.revealedGlyphs()==3&&!fast.waiting()&&!fast.finished(),"confirm clears future delay but does not force page or completion");
 check(normal.tick(false,e)&&normal.revealedGlyphs()==2,"ordinary cadence remains one glyph");
 for(unsigned i=0;i<12&&!normal.waiting();++i)check(normal.tick(false,e),"ordinary reveal reaches input boundary");
 check(fast.tick(false,e)&&fast.waiting()&&normal.waiting()&&fast.patterns()==normal.patterns(),"fast and ordinary reveal publish identical final pixels");
 check(fast.tick(false,e,true)&&fast.waiting()&&!fast.finished(),"fast pulse is not page acknowledgement");
 check(fast.acknowledge(e)&&fast.tick(false,e)&&fast.finished(),"actual input still owns terminal completion");
 const uint8_t pages[]={'A','B',0xf6,'A','B',0xff};
 check(fast.begin(pages,sizeof(pages),0,0,layout,e),"source explicit pause resets reveal context");
 for(unsigned i=0;i<3;++i)check(fast.tick(false,e,i==2),"first paused page fast reveal");
 for(unsigned i=0;i<12&&!fast.waiting();++i)check(fast.tick(false,e),"explicit pause remains a page boundary");
 check(fast.waiting()&&!fast.textEnded()&&fast.revealedGlyphs()==2,"fast reveal cannot consume source pause");
 check(fast.acknowledge(e),"real input continues paused page");
 for(unsigned i=0;i<4;++i)check(fast.tick(false,e),"clear reopen and next source delay producer");
 check(fast.revealedGlyphs()==2,"next body FC1 reinstates its own delay after fast page");
 check(fast.tick(false,e)&&fast.revealedGlyphs()==3,"next page resumes original glyph cadence");
}
void fastRevealAssets(const std::vector<uint8_t>& assets,const std::vector<uint8_t>& source,size_t at,uint16_t speaker){using namespace Snatcher;std::string e;DialogueWindow normal,fast;auto layout=freshModuleDialogueLayout();check(normal.loadAssets(assets.data(),assets.size(),e)&&fast.loadAssets(assets.data(),assets.size(),e),"original fast fixture assets");check(normal.begin(source.data(),source.size(),at,speaker,layout,e)&&fast.begin(source.data(),source.size(),at,speaker,layout,e),"original fast fixture source");
 unsigned prefix=speaker%256>1?4:2;for(unsigned i=0;i<prefix;++i)check(normal.tick(false,e)&&fast.tick(false,e),"real source body prefix");
 check(!normal.waiting()&&!fast.waiting()&&normal.patterns()==fast.patterns(),"same actual source state before semantic confirm");
 check(fast.tick(false,e,true),"actual source confirm pulse");unsigned fastTicks=1,normalTicks=0;
 while(!fast.waiting()&&fastTicks<4096){check(fast.tick(false,e),"actual fast owner updates");++fastTicks;}
 while(!normal.waiting()&&normalTicks<4096){check(normal.tick(false,e),"actual ordinary owner updates");++normalTicks;}
 std::vector<GraphicsTransfer>a,b;check(normal.waiting()&&fast.waiting()&&!fast.finished()&&fastTicks<normalTicks,"actual confirm accelerates without invented completion");check(normal.transfers(a,e)&&fast.transfers(b,e)&&a.size()==b.size(),"actual text allocations publish");for(size_t i=0;i<a.size();++i)check(a[i].destination==b[i].destination&&a[i].decoded==b[i].decoded,"complete actual allocation bytes equal at waiting boundary");check(normal.cursor()==fast.cursor()&&normal.revealedGlyphs()==fast.revealedGlyphs()&&normal.textEnded()==fast.textEnded(),"actual source continuation unchanged");std::printf("fast original fixture: prefix=%u fast_updates=%u ordinary_updates=%u glyphs=%zu; no image/reference/gameplay\n",prefix,fastTicks,normalTicks,fast.revealedGlyphs());
}
void continuationContracts(){using namespace Snatcher;std::string e;DialogueWindow w;auto assets=syntheticAssets();auto layout=freshModuleDialogueLayout();check(w.loadAssets(assets.data(),assets.size(),e),"continuation assets");
 const uint8_t automatic[]={0xf4,'A',0xf6,'B',0xff};
 check(w.begin(automatic,sizeof(automatic),0,0,layout,e),"F4 source marker accepted");
 for(unsigned i=0;i<100&&!w.waiting();++i)check(w.tick(false,e),"automatic first page reveal");
 check(w.waiting()&&w.mode()==2&&!w.textEnded(),"F4 owns prompt mode before page end");
 auto patterns=w.patterns();for(unsigned i=0;i<40;++i)check(w.tick(true,e)&&w.waiting()&&w.patterns()==patterns,"paused prompt does not advance");
 for(unsigned i=0;i<12;++i)check(w.tick(false,e)&&w.waiting(),"original first prompt frame duration");
 check(w.tick(false,e)&&!w.waiting()&&!w.finished()&&w.takeViewAction()==kDialogueCloseView,"source final prompt frame schedules close");
 check(w.takeViewAction()==kDialogueNoViewAction&&w.tick(false,e)&&w.tick(false,e)&&w.takeViewAction()==kDialogueReopenView,"source clear then reopen phases");
 for(unsigned i=0;i<100&&!w.waiting();++i)check(w.tick(false,e),"automatic continuation reveal");
 check(w.waiting()&&w.textEnded()&&w.mode()==2&&w.revealedGlyphs()==2,"mode persists across automatic pages");
 for(unsigned i=0;i<30&&!w.finished();++i)check(w.tick(false,e),"automatic terminal continuation");check(w.finished()&&w.takeViewAction()==kDialogueCloseView,"terminal automatic owner ends exactly once");
 const uint8_t text[]={'A',0xff};for(unsigned mode=0;mode<4;++mode)for(unsigned speaker=0;speaker<2;++speaker){check(w.begin(text,sizeof(text),0,uint16_t(mode*256+speaker),layout,e),"high mode independently owned");for(unsigned i=0;i<100&&!w.waiting();++i)check(w.tick(false,e),"highmode reveal");for(unsigned i=0;i<40&&!w.finished();++i)check(w.tick(false,e),"highmode prompt updates");check(w.finished()==(mode!=0&&speaker==0),"special speaker suppresses automatic prompt");if(!w.finished())check(w.acknowledge(e)&&w.tick(false,e)&&w.finished(),"manual acknowledgement remains owned");}
}
void mouseRevealContracts(){using namespace Snatcher;std::string error;DialogueWindow window;auto assets=syntheticAssets();auto layout=freshModuleDialogueLayout();
 check(!window.revealing(),"inactive window cannot expose reveal input");
 check(window.loadAssets(assets.data(),assets.size(),error),"mouse reveal assets");const uint8_t text[]={'A','B','A',0xff};
 check(window.begin(text,sizeof(text),0,0,layout,error)&&window.revealing(),"active nonmenu source reveal owns click");
 check(window.tick(false,error)&&window.tick(false,error)&&window.revealedGlyphs()==1,"source delay prefix before mouse confirm");
 MouseInput mouse;MouseContext context;context.kind=kMouseDialogue;context.generation=1;context.ready=true;context.targets.push_back(MouseTarget(MouseRect(0,0,256,224),0));
 check(mouse.handle(context,MouseEvent(kMouseLeftDown,20,20)).kind==kMouseActivate,"fresh reveal click publishes semantic confirm");
 check(window.tick(false,error,true)&&window.revealedGlyphs()==3&&!window.waiting(),"mouse pulse accelerates without acknowledgement");
 check(window.tick(false,error)&&window.waiting()&&!window.revealing(),"waiting boundary is no longer reveal input");
 check(mouse.handle(context,MouseEvent(kMouseLeftDown,20,20)).kind==kMouseNoAction&&!window.finished(),"held reveal click cannot acknowledge new waiting boundary");
 check(mouse.handle(context,MouseEvent(kMouseLeftUp,20,20)).kind==kMouseNoAction,"release does not acknowledge");
 check(mouse.handle(context,MouseEvent(kMouseLeftDown,20,20)).kind==kMouseActivate&&window.acknowledge(error),"separate fresh click acknowledges source page");
 check(!window.revealing()&&window.tick(false,error)&&window.finished(),"close transition cannot expose reveal input");
 std::vector<uint8_t> menu(0x3802,0xff);menu[0x3800]='A';check(window.beginMenu(menu.data(),menu.size(),std::vector<uint16_t>(1,0),0,layout,error)&&window.active()&&!window.revealing(),"active menu never leaks dialogue reveal context");
 window.cancel();check(!window.revealing(),"cancel releases reveal owner");
 std::printf("mouse reveal integration: %u checks,0 failures; no gameplay interaction\n",checks);
}
int main(int argc,char **argv){using namespace Snatcher;if(argc==2&&std::string(argv[1])=="--mouse-reveal"){mouseRevealContracts();return 0;}focused();continuationContracts();fastRevealContracts();if(argc==6&&std::string(argv[1])=="--fast-reveal-assets"){fastRevealAssets(bytes(argv[2]),bytes(argv[3]),size_t(std::stoul(argv[4])),uint16_t(std::stoul(argv[5])));std::printf("dialogue fast original: %u checks,0 failures\n",checks);return 0;}std::string e;DialogueWindow w;DialogueLayout config=freshModuleDialogueLayout();uint8_t text[]={0x41,0xff};check(!w.begin(text,2,0,0,config,e),"unowned original assets reject");check(!w.tick(false,e)||!w.active(),"inactive update has no activation");if(argc==1){std::printf("dialogue window: %u checks,0 failures; original fixture NOT RUN\n",checks);return 0;}if(argc==4&&std::string(argv[1])=="--corpus"){std::vector<uint8_t> sub=bytes(argv[2]);check(w.loadAssets(sub.data(),sub.size(),e),"original corpus source assets");std::ifstream in(argv[3]);std::string id,path;size_t offset;unsigned speaker;size_t accepted=0,rejected=0,voice=0,total=0;while(in>>id>>path>>offset>>speaker){++total;std::vector<uint8_t> data=bytes(path.c_str());bool ok=w.begin(data.data(),data.size(),offset,uint16_t(speaker),config,e);for(unsigned tick=0;ok&&!w.waiting()&&tick<4096;++tick)ok=w.tick(false,e);ok=ok&&w.waiting();if(ok){++accepted;if(w.mode()==2)++voice;}else{++rejected;std::printf("unsupported\t%s\t%s\n",id.c_str(),e.c_str());}}std::printf("dialogue corpus: %zu entries, %zu first pages generated, %zu unsupported, %zu automatic prompt-mode first pages\n",total,accepted,rejected,voice);return in.bad()?3:0;}if(argc!=5&&argc!=11)return 2;std::vector<uint8_t> sub=bytes(argv[1]),scenario=bytes(argv[2]);check(w.loadAssets(sub.data(),sub.size(),e),"original font speaker and prompt data load");bool menu=std::string(argv[3]).find("menu:")==0;if(menu){std::vector<uint16_t> identities;std::string rest=std::string(argv[3]).substr(5);while(!rest.empty()){size_t comma=rest.find(',');identities.push_back(uint16_t(std::stoul(rest.substr(0,comma))));if(comma==std::string::npos)break;rest.erase(0,comma+1);}check(w.beginMenu(scenario.data(),scenario.size(),identities,unsigned(std::stoul(argv[4])),config,e),"original command identity menu");}else check(w.begin(scenario.data(),scenario.size(),0x3800+std::stoul(argv[3]),uint16_t(std::stoul(argv[4])),config,e),"original source dialogue entry");size_t ticks=0;for(;ticks<4000&&!w.waiting();++ticks)check(w.tick(false,e),"deterministic original glyph update");check(w.waiting()&&!w.finished(),"page waits for actual input");std::vector<uint8_t> frozen=w.patterns();check(w.tick(true,e)&&w.patterns()==frozen,"pause preserves text state");check(w.tick(false,e),"first source prompt phase");std::vector<GraphicsTransfer> packets;check(w.transfers(packets,e)&&packets.size()==(menu?4u:3u)&&packets[0].decoded.size()==8192&&packets[1].decoded.size()==512,"owned allocations export");if(!menu){check(w.acknowledge(e),"actual acknowledgement accepted");if(w.textEnded())check(w.tick(false,e),"source terminal producer phase");check(w.finished()==w.textEnded(),"terminal state is distinct from reveal");}else check(!w.acknowledge(e),"menu choice belongs to command owner");std::printf("dialogue window: %u checks,0 failures; reveal_ticks=%zu glyphs=%zu\n",checks,ticks,w.revealedGlyphs());
 if(argc==11){std::vector<uint8_t> resource=bytes(argv[5]),paletteBytes=bytes(argv[7]);SceneAssets assets;check(parseSceneAssets(resource.data(),resource.size(),unsigned(std::stoul(argv[6])),4*1024*1024,assets,e)==kSceneAssetsReady,"original desk asset packet");SceneRenderer renderer;SceneLayout layout;layout.width=256;layout.height=224;layout.columns=32;layout.rows=64;SceneViewBand band;band.firstRow=menu?137:144;band.sourceY[0]=band.sourceY[1]=256;layout.viewBands.push_back(band);check(renderer.configure(layout,e)&&renderer.establishSceneReset(kSceneTallLayout,e),"explicit observed source view fixture");for(const GraphicsTransfer&t:assets.transfers)check(renderer.applyTransfer(t,e),"resource allocations");for(const GraphicsTransfer&t:packets)check(renderer.applyTransfer(t,e),"native owned dialogue allocations");std::vector<PlacedPiece> drawList;if(menu)check(w.menuPieces(drawList,e),"native original menu cursor geometry");std::ifstream in(argv[9]);std::string kind;while(in>>kind){if(kind!="actor")return 3;unsigned table,frame,style,paletteOverride;int x,y;if(!(in>>table>>frame>>x>>y>>style>>paletteOverride))return 3;std::vector<FramePiece> geometry;std::vector<PlacedPiece> pieces;FramePlacement p;p.x=x;p.y=y;p.flipX=(style&1)!=0;p.flipY=(style&2)!=0;p.overridePalette=(paletteOverride&128)!=0;p.palette=paletteOverride&3;check(readFrameGeometry(resource.data(),resource.size(),table,frame,4096,geometry,e)&&placeFrame(geometry,p,4096,pieces,e),"explicit original actor state");drawList.insert(drawList.end(),pieces.begin(),pieces.end());}std::vector<uint16_t> palette;for(size_t i=0;i<paletteBytes.size();i+=2)palette.push_back(uint16_t(uint16_t(paletteBytes[i])<<8|paletteBytes[i+1]));SceneImage image;check(renderer.setPalette(palette,0,e)&&renderer.render(drawList,kSceneReferenceRGB565,image,e),"generalized full frame compose");std::ofstream out(argv[8],std::ios::binary);out.write(reinterpret_cast<const char*>(image.rgb.data()),image.rgb.size());std::ofstream patterns(argv[10],std::ios::binary);patterns.write(reinterpret_cast<const char*>(packets[0].decoded.data()),packets[0].decoded.size());check(bool(out)&&bool(patterns),"private native image export");}
 return 0;
}
